-- RawGpsSimSvr query.sql (PostgreSQL / libpq: $1, $2, ...)
-- 도로망(ruc.road_link)에서 경로 링크를 조회하고, ruc.prim_rawgps 에 원시 GPS 를 적재한다.
-- (2026-08-11 최정우 수정 — 로컬 ruc DB 전환. PostGIS 없음: coords(jsonb, WGS-84)에서
--  WKT LINESTRING 문자열을 직접 조립해 기존 CGeoUtil::ParseLineString 파서를 그대로 재사용)
--
-- coords 형태: [[[lon,lat], [lon,lat], ...]] — road_link 는 항상 단일 라인파트(len=1) 확인됨.
-- bbox 컬럼(min_lon/min_lat/max_lon/max_lat)이 이미 WGS-84라 SRID 변환 불필요.
-- (2026-08-12 최정우 추가 — moct_link_seed/moct_link_next 에 link_id 화이트리스트 추가.
--  web/nodelink-geumto.html 의 geumto-data(568건)에서 뽑은 목록과 동일 — 지도에 표출되는
--  링크만 시뮬레이터가 다니도록 제한. 지도 데이터 갱신 시 이 두 ARRAY 도 같이 재생성할 것.)

-- ── 도로망 SRID 감지 (ruc.road_link 는 이미 WGS-84 고정이라 상수 반환) ─────
[srid_detect]
SELECT 4326;

-- ── 시작 링크 (bounding box 내 임의 1개) ──────────────────────────────────
-- $1=min_lon $2=min_lat $3=max_lon $4=max_lat $5=limit(=1)
-- TEMP(2026-08-12 최정우): 폐쇄형 구역(RL-Z00005, 입구TG00007→출구TG00008, 코드상 실거리
--   370.3m) 진입 전 여유 구간을 두기 위해, 구역 진입 링크(2040423801)로 바로 들어가지 않고
--   그 앞단 접근 링크(2040424701, f_node=2040155704→t_node=2040155605=구역 진입 노드)를
--   시작 링크로 강제. min_m=2000 이 구역 길이(370.3m)의 2배(740.5m)를 훨씬 넘어 출구
--   통과 후에도 자연스럽게 더 이어짐 — 출발/도착 모두 구역 앞뒤로 여유 확보됨.
--   아래 AND link_id='2040424701' 한 줄이 강제 조건. 확인 끝나면 그 줄만 삭제할 것.
--   주의: 이 SQL 파서(SQLAccessor::Load)는 줄을 개행 없이 이어붙이고 '#'로 시작하는 줄만
--   주석 처리함 — SQL 코드 줄 뒤에 '--' 인라인 주석을 달면 뒤따르는 나머지 문장이 통째로
--   주석 처리돼 깨지니 반드시 별도 줄로만 주석을 달 것 (2026-08-12 최정우, 직접 겪은 버그)
[moct_link_seed]
SELECT
	link_id,
	COALESCE(t_node, '') AS t_node,
	COALESCE(max_spd, 0) AS max_spd,
	'LINESTRING(' || (
		SELECT string_agg((elem->>0) || ' ' || (elem->>1), ',' ORDER BY ord)
		FROM jsonb_array_elements(coords->0) WITH ORDINALITY AS t(elem, ord)
	) || ')' AS wkt,
	COALESCE(road_type, '000') AS road_type,
	COALESCE(f_node, '') AS f_node
FROM ruc.road_link
WHERE min_lon <= $3::float8 AND max_lon >= $1::float8
	AND min_lat <= $4::float8 AND max_lat >= $2::float8
	AND COALESCE(road_use, '0') = '0'
	AND t_node IS NOT NULL
